-- ThorPDV Fiscal v0.7.5
-- Multiple NF-e/NFC-e series, controlled last number, POS-to-NFC-e series mapping,
-- DANFE preferences, encrypted CSC and tenant CFOP catalog.

create table if not exists public.fiscal_series (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id) on delete cascade,
  company_id uuid not null references public.companies(id) on delete cascade,
  branch_id uuid not null references public.branches(id) on delete cascade,
  document_type text not null check (document_type in ('nfe','nfce')),
  series integer not null check (series between 1 and 999),
  label text,
  last_number bigint not null default 0 check (last_number between 0 and 999999999),
  is_default boolean not null default false,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (tenant_id,branch_id,document_type,series)
);
create unique index if not exists fiscal_series_one_default_idx on public.fiscal_series(tenant_id,branch_id,document_type) where is_default and active;
create index if not exists fiscal_series_branch_idx on public.fiscal_series(tenant_id,branch_id,document_type,active);
alter table public.fiscal_series enable row level security;
drop policy if exists tenant_access_fiscal_series on public.fiscal_series;
create policy tenant_access_fiscal_series on public.fiscal_series for all using (public.is_tenant_member(tenant_id)) with check (public.is_tenant_member(tenant_id));

create table if not exists public.fiscal_pos_series (
  id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,
  company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid not null references public.branches(id) on delete cascade,
  pos_register_id uuid not null references public.pos_registers(id) on delete cascade,fiscal_series_id uuid not null references public.fiscal_series(id) on delete cascade,
  cash_number text not null,in_use boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create unique index if not exists fiscal_pos_series_active_pos_idx on public.fiscal_pos_series(tenant_id,pos_register_id) where in_use;
create unique index if not exists fiscal_pos_series_active_series_idx on public.fiscal_pos_series(tenant_id,fiscal_series_id) where in_use;
create unique index if not exists fiscal_pos_series_active_cash_idx on public.fiscal_pos_series(tenant_id,branch_id,cash_number) where in_use;
alter table public.fiscal_pos_series enable row level security;
drop policy if exists tenant_access_fiscal_pos_series on public.fiscal_pos_series;
create policy tenant_access_fiscal_pos_series on public.fiscal_pos_series for all using (public.is_tenant_member(tenant_id)) with check (public.is_tenant_member(tenant_id));

create table if not exists public.fiscal_danfe_settings (
  id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,
  company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid not null references public.branches(id) on delete cascade,
  unit_decimal_places smallint not null default 2 check (unit_decimal_places between 2 and 6),
  product_name_lines smallint not null default 2 check (product_name_lines between 1 and 5),
  item_order text not null default 'launch' check (item_order in ('alphabetical','launch','internal_code')),
  product_name_format text not null default '{nome}',active boolean not null default true,
  created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,branch_id)
);
alter table public.fiscal_danfe_settings enable row level security;
drop policy if exists tenant_access_fiscal_danfe_settings on public.fiscal_danfe_settings;
create policy tenant_access_fiscal_danfe_settings on public.fiscal_danfe_settings for all using (public.is_tenant_member(tenant_id)) with check (public.is_tenant_member(tenant_id));

create table if not exists public.fiscal_cfops (
  id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,
  code text not null check(code~'^[0-9]{4}$'),name text not null,active boolean not null default true,
  created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,code)
);
alter table public.fiscal_cfops enable row level security;
drop policy if exists tenant_access_fiscal_cfops on public.fiscal_cfops;
create policy tenant_access_fiscal_cfops on public.fiscal_cfops for all using (public.is_tenant_member(tenant_id)) with check (public.is_tenant_member(tenant_id));

create table if not exists private.fiscal_csc_credentials (
 tenant_id uuid not null references public.tenants(id) on delete cascade,company_id uuid not null references public.companies(id) on delete cascade,
 branch_id uuid not null references public.branches(id) on delete cascade,csc_id text,csc_token_cipher bytea,updated_at timestamptz not null default now(),primary key(tenant_id,branch_id)
);

