 (p_tenant,'1917','Entrada de mercadoria recebida em consignação mercantil ou industrial',true),(p_tenant,'1926','Lançamento efetuado a título de reclassificação de mercadoria decorrente de formação de kit ou de sua desagregação',true),
 (p_tenant,'1949','Outra entrada de mercadoria ou prestação de serviço não especificada',true),(p_tenant,'2102','Compra para comercialização',true),(p_tenant,'2152','Transferência para comercialização',true),
 (p_tenant,'2201','Devolução de venda de produção do estabelecimento',true),(p_tenant,'2403','Compra para comercialização em operação com mercadoria sujeita ao regime de substituição tributária',true),
 (p_tenant,'2411','Devolução de venda de mercadoria adquirida ou recebida de terceiros em operação com mercadoria sujeita ao regime de substituição tributária',true),(p_tenant,'3102','Compra para comercialização',true),
 (p_tenant,'5101','Venda de produção do estabelecimento',true),(p_tenant,'5102','Venda de mercadoria adquirida ou recebida de terceiros, ou qualquer venda de mercadoria efetuada pelo MEI com exceção das saídas classificadas nos códigos 5.501, 5.502, 5.504 e 5.505 / 6.501, 6.502, 6.504 e 6.505',true),
