 (p_tenant,'5401','Venda de produção do estabelecimento em operação com produto sujeito ao regime de substituição tributária, na condição de contribuinte substituto',true),
 (p_tenant,'5403','Venda de mercadoria, adquirida ou recebida de terceiros, sujeita ao regime de substituição tributária, na condição de contribuinte-substituto',true),
 (p_tenant,'5405','Venda de mercadoria, adquirida ou recebida de terceiros, sujeita ao regime de substituição tributária, na condição de contribuinte-substituído',true),
 (p_tenant,'5655','Venda de combustível ou lubrificante adquirido ou recebido de terceiros destinado à comercialização',true),(p_tenant,'5910','Remessa em bonificação, doação ou brinde',true),
 (p_tenant,'5917','Remessa de mercadoria em consignação mercantil ou industrial',true),(p_tenant,'5922','Lançamento efetuado a título de simples faturamento decorrente de venda para entrega futura',true),
 (p_tenant,'5926','Lançamento efetuado a título de reclassificação de mercadoria decorrente de formação de kit ou de sua desagregação',true),(p_tenant,'5927','Lançamento efetuado a título de baixa de estoque decorrente de perda, roubo ou deterioração',true),
 (p_tenant,'5929','Lançamento efetuado em decorrência de emissão de documento fiscal relativo a operação ou prestação também registrada em equipamento Emissor de Cupom Fiscal - ECF',true),(p_tenant,'5949','Outra saída de mercadoria ou prestação de serviço não especificado',true),
 (p_tenant,'6102','Venda de mercadoria adquirida ou recebida de terceiros, ou qualquer venda de mercadoria efetuada pelo MEI com exceção das saídas classificadas nos códigos 5.501, 5.502, 5.504 e 5.505 / 6.501, 6.502, 6.504 e 6.505',true),
